### 代码审查重点关注点（Java方向）

#### 1. **代码规范与可读性**  
**为什么重要**：统一的编码规范能降低维护成本，避免歧义。  
**怎么做**：  
- 检查命名是否语义化（如`calculateOrderTotal()`优于`calc()`）。  
- 验证是否符合团队规范（如阿里巴巴Java开发手册）。  
- 示例：  
  ```java
  // 反例：变量名无意义  
  int a = user.getAge() * 2;  
  // 正例：明确业务含义  
  int bonusAge = user.getAge() * 2;  
  ```

---

#### 2. **性能隐患**  
**为什么重要**：低效代码可能导致高并发场景下系统崩溃。  
**怎么做**：  
- 排查资源未释放（如数据库连接、文件流）。  
- 检查循环内重复计算或频繁对象创建。  
- 示例：  
  ```java
  // 反例：循环内重复查询数据库  
  for (User user : users) {  
      List<Order> orders = orderDao.findByUserId(user.getId()); // 应批量查询  
  }  
  ```

---

#### 3. **安全性漏洞**  
**为什么重要**：安全漏洞可能引发数据泄露或攻击。  
**怎么做**：  
- 检查SQL注入风险（是否使用`PreparedStatement`）。  
- 验证敏感信息是否硬编码（如密码、密钥）。  
- 示例：  
  ```java
  // 反例：拼接SQL导致注入风险  
  String sql = "SELECT * FROM users WHERE id = " + userId;  
  // 正例：参数化查询  
  String sql = "SELECT * FROM users WHERE id = ?";  
  preparedStatement.setInt(1, userId);  
  ```

---

#### 4. **异常处理与日志**  
**为什么重要**：不合理的异常处理会掩盖问题或导致系统不稳定。  
**怎么做**：  
- 检查是否捕获了具体异常而非`Exception`。  
- 验证日志是否包含关键上下文（如请求ID、用户ID）。  
- 示例：  
  ```java
  // 反例：空catch块  
  try { ... } catch (Exception e) {}  
  // 正例：记录详细日志并抛出业务异常  
  catch (SQLException e) {  
      log.error("订单查询失败, userId={}", userId, e);  
      throw new OrderNotFoundException("订单不存在");  
  }  
  ```

---

#### 5. **测试覆盖**  
**为什么重要**：缺乏测试的代码难以保证可靠性。  
**怎么做**：  
- 检查单元测试是否覆盖边界条件（如空值、极端数值）。  
- 验证Mock是否合理（如模拟外部依赖）。  
- 示例：  
  ```java
  @Test  
  void testCalculateDiscount() {  
      // 边界测试：金额为0  
      assertEquals(0, discountService.calculate(0));  
      // 正常测试  
      assertEquals(10, discountService.calculate(100));  
  }  
  ```

---

**总结**：代码审查需从规范、性能、安全、异常处理、测试五个维度切入，结合静态工具（如SonarQube）和人工校验，确保代码健壮性与可维护性。'),
