### 自我介绍参考答案

**各位面试官好，我是XXX，目前就读于XX大学计算机专业。接下来重点介绍我在Spring Boot项目中的实践经验：**

#### 1. **项目概述与技术栈**  
我主导开发了一个**企业级任务管理系统**，核心模块包括用户管理、任务分配和进度追踪。技术栈采用Spring Boot 2.7 + MyBatis + MySQL，通过RESTful API与前端交互。  
**为什么选Spring Boot？** 它简化了配置（如自动装配、内嵌Tomcat），适合快速迭代；**怎么做？** 通过`@SpringBootApplication`启动项目，用`application.yml`集中管理配置，例如：  
```yaml
spring:
  datasource:
    url: jdbc:mysql://localhost:3306/task_db
```

#### 2. **接口设计与参数处理**  
- **接口设计**：遵循RESTful规范，例如任务创建接口`POST /api/tasks`，通过`@RestController`暴露端点。  
  **为什么？** RESTful语义清晰，便于前后端分离；**怎么做？** 用`@PostMapping`定义路由，参数通过`@RequestBody`接收JSON数据。  
- **参数校验**：使用`@Valid` + `JSR-303`注解（如`@NotBlank`）校验前端输入。  
  **为什么？** 避免脏数据入库；**怎么做？** 在DTO类定义校验规则，结合`@ControllerAdvice`统一处理异常：  
  ```java
  @ControllerAdvice
  public class GlobalExceptionHandler {
      @ExceptionHandler(MethodArgumentNotValidException.class)
      public ResponseEntity handleValidationErrors(...) { ... }
  }
  ```

#### 3. **功能迭代与工程实践**  
- **版本控制**：采用Git分支策略（`feature/xxx` → `develop` → `master`），通过Jenkins实现CI/CD。  
  **为什么？** 保证代码质量；**怎么做？** 每次提交触发自动化测试（JUnit + Mockito），通过后自动部署到测试环境。  
- **日志与监控**：集成SLF4J + Logback记录关键操作，通过`@Slf4j`注解打印调试信息。  

#### 4. **典型场景示例**  
在任务状态更新功能中，需校验用户权限：  
```java
@PostMapping("/tasks/{id}/status")
public ResponseEntity updateStatus(@PathVariable Long id, @RequestBody @Valid StatusUpdateRequest req) {
    userService.checkPermission(id, req.getUserId()); // 权限校验
    taskService.updateStatus(id, req.getStatus());
    return ResponseEntity.ok().build();
}
```  
**架构流程**：  
```
Client -> @RestController -> @Service -> @Repository -> MySQL
```

**总结**：通过这个项目，我掌握了Spring Boot全栈开发流程，尤其在接口设计、参数安全和工程化协作方面积累了实战经验。期待在贵司发挥技术价值！**'),
  ('other-976', '

MyBatis-Plus（简称MP）是MyBatis的增强工具，核心目标是**简化CRUD操作、减少重复开发**，同时保留MyBatis的灵活性。在项目中的具体作用可总结为以下四点：

---

### 1. **通用CRUD能力**  
**为什么需要？**  
传统MyBatis需手动编写大量重复SQL（如增删改查），而MP通过`BaseMapper`接口提供通用方法，直接操作数据库。  
**怎么做？**  
```java
// 继承BaseMapper，无需写SQL
public interface UserMapper extends BaseMapper<User> {}
// 直接调用：insert、selectById、updateById等
userMapper.insert(new User());
```  
**场景**：用户注册时，仅需调用`insert`方法，无需编写`INSERT INTO`语句。

---

### 2. **代码生成器**  
**为什么需要？**  
减少实体类、Mapper、Service层的重复开发。  
**怎么做？**  
通过配置`AutoGenerator`，一键生成基础代码：  
```java
AutoGenerator generator = new AutoGenerator();
generator.setDataSource(dataSourceConfig);
generator.setStrategy(strategyConfig);
generator.execute();
```  
**场景**：新建订单模块时，自动生成`Order`实体、`OrderMapper`、`OrderService`，节省50%+基础代码量。

---

### 3. **分页插件**  
**为什么需要？**  
原生MyBatis分页需手动拼接`LIMIT`，MP通过`PaginationInterceptor`自动处理。  
**怎么做？**  
```java
// 配置分页插件
@Bean
public MybatisPlusInterceptor interceptor() {
    MybatisPlusInterceptor interceptor = new MybatisPlusInterceptor();
    interceptor.addInnerInterceptor(new PaginationInnerInterceptor());
    return interceptor;
}
// 使用Page对象
Page<User> page = new Page<>(1, 10);
userMapper.selectPage(page, null);
```  
**场景**：用户列表分页查询时，自动转换为`SELECT * FROM user LIMIT 0,10`。

---

### 4. **逻辑删除与字段自动填充**  
**为什么需要？**  
避免物理删除数据，同时自动处理`create_time`等字段。  
**怎么做？**  
```java
// 实体类标注
@TableLogic
private Boolean deleted;
@TableField(fill = FieldFill.INSERT)
private LocalDateTime createTime;
// 配置元数据处理器
@Component
public class MyMetaObjectHandler implements MetaObjectHandler {
    @Override
    public void insertFill(MetaObject metaObject) {
        this.strictInsertFill(metaObject, "createTime", LocalDateTime::now, LocalDateTime.class);
    }
}
```  
**场景**：删除用户时，自动将`deleted`字段置为1，而非执行`DELETE`语句。

---

### 总结  
MyBatis-Plus通过**封装通用能力**（CRUD、分页、代码生成）和**扩展机制**（逻辑删除、字段填充），显著提升开发效率，同时保留复杂SQL的自定义空间。在美团项目中，我们用它快速构建用户、订单等模块的基础功能，将开发重点聚焦在业务逻辑而非重复代码上。'),
  ('other-978', '

### 参考答案  
这一年我通过「理论+实践+复盘」三位一体的方式系统提升技能，具体分为四个维度：  

**1. 理论学习：夯实底层基础**  
- **为什么**：Java生态迭代快，但核心原理（如JVM、并发）是长期价值所在。  
- **怎么做**：每周精读《深入理解Java虚拟机》等经典书籍，用思维导图梳理知识体系（如GC算法对比），并针对难点写技术笔记（例如通过`jstat`命令验证老年代回收逻辑）。  

**2. 项目实践：聚焦高并发场景**  
- **为什么**：真实业务能暴露理论盲区，比如缓存穿透、分布式事务问题。  
- **怎么做**：主导重构公司内部订单系统，采用「Redis+Lua脚本」解决超卖问题（伪代码示例：`EVAL "if redis.call(''get'', KEYS[1]) >= tonumber(ARGV[1]) then return 0 end return redis.call(''decr'', KEYS[1])" 1 stock_key 100`），将QPS从2k提升至8k。  

**3. 问题解决：建立方法论**  
- **为什么**：线上故障处理是检验技术深度的关键。  
- **怎么做**：某次接口延迟突增时，通过`Arthas`定位到慢SQL，结合执行计划优化索引，并推动团队建立SQL审核规范。总结为「监控告警→工具定位→根因分析→流程固化」四步法。  

**4. 知识输出：形成闭环**  
- **为什么**：费曼学习法能暴露认知漏洞。  
- **怎么做**：在团队内分享《Spring Boot自动装配原理》，用ASCII图讲解启动流程：  
  ```  
  SpringApplication.run()  
  ├── 加载配置类 |-> @SpringBootApplication  
  ├── 初始化ApplicationContext  
  └── 触发自动配置 |-> META-INF/spring.factories  
  ```  
  收到反馈后补充了条件注解的源码解析。  

**总结**：通过「输入-实践-输出」循环，既保证了技术广度（如微服务、中间件），又深化了核心领域（JVM调优、高并发设计），最终实现从「会用工具」到「能解决复杂问题」的跃迁。'),
