### 实习项目拷打参考答案（Java后端）

#### 1. **项目架构设计**  
**为什么**：高并发场景下，单体架构易成为瓶颈，需通过微服务拆分提升可扩展性。  
**怎么做**：  
- 采用Spring Cloud Gateway作为API网关，统一鉴权与限流。  
- 核心服务按业务域拆分（如用户/订单/支付），通过Feign实现服务间调用。  
```plaintext
Client -> API Gateway -> Auth Service -> Order Service -> MySQL
```  
- 使用Nacos做配置中心与注册中心，动态调整服务参数。

#### 2. **数据库优化**  
**为什么**：订单表数据量达千万级时，单表查询延迟超500ms，需优化存储与查询效率。  
**怎么做**：  
- 分库分表：按用户ID哈希分片，主键用雪花算法避免跨库主键冲突。  
- 索引策略：对高频查询字段（如`user_id`+`status`）建联合索引，通过`EXPLAIN`验证执行计划。  
```sql
CREATE INDEX idx_user_status ON orders(user_id, status);
```

#### 3. **高并发处理**  
**为什么**：秒杀场景下瞬时QPS达5万，直接查库会导致数据库崩溃。  
**怎么做**：  
- 多级缓存：Redis缓存热点数据（如商品信息），本地Caffeine缓存用户权限。  
- 消息队列削峰：Kafka异步处理订单创建，消费者分批写入数据库。  
- 限流降级：Sentinel配置QPS阈值，超限时返回友好提示。

#### 4. **系统监控与日志**  
**为什么**：线上故障需快速定位，传统日志分散难以追溯。  
**怎么做**：  
- ELK栈集中采集日志，通过TraceID串联全链路调用。  
- Prometheus+Grafana监控JVM/GC指标，设置CPU>80%告警规则。  

**总结**：通过模块化设计、分层缓存、异步解耦三大策略，支撑日均百万级订单处理，系统可用性达99.95%。'),
  ('other-983', '

### 参考答案

**1. 问题识别与定位**  
- **为什么**：作为Owner需快速定位问题根源，避免资源浪费。例如某次实习中，系统突发高延迟，若直接扩容可能掩盖真实问题。  
- **怎么做**：通过日志聚合工具（ELK）分析请求链路，发现数据库慢查询占比达60%。用`EXPLAIN`分析SQL执行计划，定位到未命中索引的关联查询。  
```sql
-- 优化前：全表扫描  
SELECT * FROM orders o JOIN users u ON o.user_id = u.id WHERE u.status = ''active'';  
-- 优化后：添加联合索引  
CREATE INDEX idx_user_status ON users(status);
```

**2. 跨团队协作**  
- **为什么**：问题涉及多团队（如DBA、前端），需统一目标。  
- **怎么做**：组织三方会议明确责任：DBA优化索引，前端减少非必要请求。用Jira拆分任务并设置每日站会同步进度。  
```
[前端] -> [API Gateway] -> [Order Service] -> [MySQL]  
          ↑ 缓存层(Redis)  ↓ 慢查询优化
```

**3. 技术方案设计**  
- **为什么**：短期优化需配合长期架构改进。  
- **怎么做**：引入Redis缓存热点数据，设计双层缓存策略（本地Caffeine + Redis），用`@Cacheable`注解实现代码无侵入改造。  
```java
@Cacheable(value = "userOrders", key = "#userId")  
public List<Order> getOrdersByUser(String userId) { ... }
```

**4. 执行与跟进**  
- **为什么**：确保方案落地且可量化。  
- **怎么做**：分阶段灰度发布，通过Grafana监控P99延迟从800ms降至200ms。建立定期巡检机制，将慢查询告警接入钉钉机器人。  

**结果**：系统吞吐量提升3倍，获团队季度创新奖。此经历让我深刻理解Owner需兼具技术深度与协作能力。'),
