在项目中，我主要运用了以下三类技术方案解决实际问题：

**1. LRU缓存算法优化热点数据访问**  
*为什么*：电商秒杀场景下，热门商品信息查询量激增，直接查库会导致数据库压力过大。  
*怎么做*：基于LinkedHashMap实现本地缓存层，重写`removeEldestEntry`方法控制容量，配合定时任务同步数据库变更。  
```java
class HotProductCache extends LinkedHashMap<String, Product> {
    public HotProductCache(int maxSize) {
        super(maxSize, 0.75f, true);
    }
    @Override
    protected boolean removeEldestEntry(Map.Entry eldest) {
        return size() > maxSize;
    }
}
```
该方案使QPS提升3倍，数据库CPU占用下降60%。

**2. 布隆过滤器防缓存穿透**  
*为什么*：恶意请求大量不存在的商品ID，导致缓存击穿。  
*怎么做*：在Redis集群部署Bloom Filter模块，业务层先校验元素存在性再查缓存：  
```java
if (bloomFilter.exists(productId)) {
    product = cache.get(productId);
}
```
通过哈希函数组合判断，误判率控制在0.1%，有效拦截99%无效请求。

**3. Hutool工具类提升开发效率**  
*为什么*：重复实现加解密、日期转换等基础功能浪费资源。  
