  |-> RocketMQ -> Payment Service  
  ```  

---

#### **2. 技术难点：缓存与数据库一致性**  
- **为什么难**：高并发下缓存更新滞后导致数据不一致，例如用户下单后库存未及时同步。  
- **怎么做**：  
  - 设计 **延迟双删策略**：先删缓存，再更新数据库，最后异步二次删缓存，避免脏读。  
  - 通过 **Canal监听MySQL binlog**，实时同步数据变更到Redis，保证强一致性场景下的可靠性。  
  - 个人贡献：优化后缓存命中率从65%提升至92%，订单处理延迟降低40%。  

---

#### **3. 个人贡献与成果**  
- **性能优化**：通过 **分库分表（ShardingSphere）** 解决单表数据量过亿问题，查询响应时间从800ms降至150ms。  
- **故障排查**：定位线上OOM问题，发现是 **MyBatis结果集未关闭** 导致内存泄漏，修复后系统稳定性提升99.9%。  
- **团队协作**：推动 **Jenkins+Docker CI/CD流程**，部署效率提升60%，代码回滚时间缩短至5分钟内。  

---

