---

#### 2. 线上部署流程  
**为什么**：通过CI/CD实现自动化部署，减少人为错误，保障高可用（如灰度发布）。  
**怎么做**：  
- **流程**：  
  ```
  Git Push -> Jenkins触发构建 -> Docker镜像打包 -> K8s滚动更新  
