### 核心项目：顺丰物流追踪系统（微服务架构）

#### 一、业务场景  
该系统支撑顺丰全网包裹实时追踪功能，日均处理**10亿+**物流状态更新请求，覆盖收件、中转、派送全链路。核心挑战在于：  
- **高并发**：双11期间峰值QPS达50万  
- **低延迟**：用户查询响应需<200ms  
- **数据一致性**：跨节点物流状态同步  

#### 二、个人核心职责  
1. **微服务架构设计**  
   - **为什么**：单体架构无法应对弹性扩缩容需求  
   - **怎么做**：  
     ```mermaid
     Client -> API Gateway -> Auth Service -> Order Service -> MySQL
                                          |-> Redis Cache
                                          |-> RabbitMQ (异步状态同步)
     ```  
     - 使用Spring Cloud Gateway实现路由/限流  
     - 通过Feign声明式调用解耦服务依赖  

2. **数据库性能优化**  
   - **为什么**：原MySQL单表超5亿行导致查询超时  
   - **怎么做**：  
     - 按区域分库（8库）+ 按时间分表（365表/库）  
     - 引入ShardingSphere实现动态路由  
     - 热点数据（如最新状态）存入Redis Cluster  

3. **分布式事务保障**  
   - **为什么**：订单状态与物流轨迹需强一致性  
   - **怎么做**：  
     - 采用TCC模式（Try-Confirm-Cancel）  
     - 关键路径使用Seata AT模式兜底  

#### 三、技术亮点  
- **异步化改造**：通过RabbitMQ削峰填谷，将同步状态更新转为异步处理，吞吐量提升3倍  
- **监控体系**：集成Prometheus+Grafana实现接口耗时/错误率实时监控  
- **容灾方案**：异地双活部署，RTO<30s，RPO=0  

