### 项目介绍与核心工作（Java后端方向）

**1. 项目背景与定位**  
我负责的得物商品交易核心系统，是一个日均千万级订单量的分布式电商平台。系统采用微服务架构，核心模块包括商品管理、订单履约、库存同步等。我主导了**高并发场景下的库存一致性保障**和**分布式事务优化**两个关键模块。

**2. 核心工作与技术深度**  
- **分布式锁防超卖方案**  
  *为什么*：传统数据库乐观锁在秒杀场景下存在性能瓶颈，且无法解决缓存与数据库双写一致性问题。  
  *怎么做*：设计Redis+Lua脚本实现分布式锁，结合本地缓存预扣库存。通过`SETNX`原子操作锁定商品ID，扣减库存后异步同步数据库。  
  ```java
  // 核心代码片段
  String lockKey = "stock:" + skuId;
  if (redis.setIfAbsent(lockKey, "locked", Duration.ofSeconds(10))) {
      int stock = redis.decr(lockKey + ":stock");
      if (stock >= 0) {
          // 异步发送MQ更新数据库
      }
  }
  ```

- **分库分表下的订单查询优化**  
  *为什么*：单表数据量突破5000万后，按用户ID查询响应时间超过2秒，影响用户体验。  
  *怎么做*：采用ShardingSphere实现分库分表，通过用户ID哈希路由到对应分片。针对跨分片查询，构建Elasticsearch实时索引，将查询响应时间优化至200ms内。

**3. 架构设计亮点**  
```plaintext
Client -> API Gateway -> Order Service
                          |-> Inventory Service (Redis Cluster)
                          |-> Payment Service
                          |-> ShardingSphere Proxy -> MySQL Cluster
```
- 通过API网关实现限流熔断，保护后端服务  
- 使用RocketMQ实现订单状态最终一致性，异步解耦支付与库存模块  

**4. 业务价值**  
- 库存超卖率从0.1%降至0.001%  
- 大促期间系统可用性达99.99%，支撑单日峰值QPS 12万+  
- 通过分库分表方案节省数据库成本40%  

（注：实际面试中可补充具体监控指标、故障排查案例等细节）'),
