### 参考答案（400-600字）  

#### 1. **项目最大并发量及评估**  
- **为什么**：当前项目通过压力测试（如JMeter模拟10万QPS）验证，核心链路（如订单服务）在Redis缓存命中率80%、MySQL读写分离架构下，峰值并发可达**8万QPS**，平均响应时间<200ms。  
- **评估标准**：  
  - **业务维度**：若为打车场景，早晚高峰需支撑15万QPS，当前值仅覆盖70%需求，存在瓶颈。  
  - **技术维度**：数据库连接池占用率超80%，API网关CPU使用率达90%，表明资源接近饱和。  

#### 2. **优化方向与方案**  
- **算法模型优化**  
  - **为什么**：实时推荐服务中，模型推理耗时占请求总时长的40%，成为性能瓶颈。  
  - **怎么做**：  
    - 模型轻量化：用TensorRT量化FP16模型，推理速度提升3倍。  
    - 异步预计算：将非实时特征（如用户画像）离线计算，在线仅调用轻量级模型。  
    ```python
    # 示例：异步特征预加载
    @celery.task
    def preload_features(user_id):
        features = fetch_offline_features(user_id)
        redis.setex(f"features:{user_id}", 300, features)
    ```  

- **缓存策略升级**  
  - **为什么**：热点数据（如热门路线）频繁穿透至数据库，导致MySQL负载过高。  
  - **怎么做**：  
    - 多级缓存：本地缓存（Caffeine）+ Redis，热点数据命中率提升至95%。  
    - 缓存预热：定时任务提前加载高峰时段数据。  
    ```
    Client -> API Gateway -> [本地缓存] -> Redis -> DB
    ```  

- **异步化与削峰**  
  - **为什么**：订单创建等写操作阻塞主链路，影响整体吞吐量。  
  - **怎么做**：  
    - 引入RocketMQ异步处理非核心逻辑（如积分计算），主链路响应时间缩短50%。  
    ```
    Order Service -> RocketMQ -> Integral Service
    ```  

- **数据库优化**  
  - **为什么**：分库分表策略未覆盖历史数据，单表数据量超5000万行，查询延迟高。  
  - **怎么做**：  
    - 冷热数据分离：近3个月数据存SSD，历史数据归档至HBase。  
    - 索引优化：对高频查询字段（如`order_status`）建立联合索引。  

#### 3. **总结**  
当前并发量在技术层面达标，但业务增长下需持续优化。通过**算法效率提升、缓存分层、异步解耦、存储优化**四维改造，预计可支撑20万QPS，同时降低30%资源成本。  

（注：实际面试中可结合具体项目数据调整数值，重点体现系统性优化思路）'),
