### 参考答案：

**1. 需求分析与拆解（Why & How）**  
- **为什么**：明确业务目标和技术边界是项目成功的基础，避免开发偏离方向。  
- **怎么做**：  
  - 与产品/业务方对齐需求，输出PRD文档，明确核心指标（如日处理10TB日志数据、延迟<5秒）。  
  - 拆解技术难点：例如实时性要求→流计算方案；数据倾斜→分桶策略。  
  - **示例**：若需求为“实时统计用户行为”，需确认统计维度（UV/PV）、时间窗口（滑动/滚动）、输出格式（Kafka/ES）。

**2. 技术选型与架构设计（Why & How）**  
- **为什么**：合理选型平衡性能、成本和团队技术栈。  
- **怎么做**：  
  - 根据数据量级选工具：  
    - 批量处理→Spark（Tera级）；流处理→Flink（低延迟）；  
    - 存储选型→HDFS（冷数据）+ ClickHouse（OLAP查询）。  
  - **架构示例**：  
    ```
    数据源 → Kafka → Flink → Redis(缓存) + ClickHouse(分析)  
    ```  
  - 设计容灾方案：Kafka副本数≥3，Flink Checkpoint间隔10秒。

**3. 开发实施与验证（Why & How）**  
- **为什么**：通过原型验证可行性，降低后期返工风险。  
- **怎么做**：  
  - 快速搭建MVP：用Flink SQL实现核心逻辑（如窗口聚合），验证吞吐量。  
