  - 压力测试：模拟10万QPS输入，观察资源占用和延迟。

**4. 上线与持续优化（Why & How）**  
- **为什么**：生产环境需保障稳定性与可扩展性。  
- **怎么做**：  
  - 灰度发布：先切10%流量验证，监控Prometheus指标（CPU/内存/反压）。  
