`Client -> API Gateway -> Cache (Redis) -> DB`  
结果：响应时间从500ms降至100ms，QPS提升3倍。

**2. 为什么具体挑战能证明能力？怎么做？**  
面对高并发场景，为什么需要系统性思维？因为局部优化可能引发新问题。怎么做？我主导设计熔断机制，当DB负载超阈值时自动降级。例如，用Hystrix监控调用链，失败率超20%时触发熔断，避免雪崩。这体现了从单点修复到架构级思考的跃迁。

**3. 为什么实习促进成长？怎么做？**  
为什么实习比竞赛更贴近工程？因为真实项目需平衡技术债与业务目标。怎么做？我建立技术复盘机制，每周沉淀最佳实践（如日志规范），并推动团队代码Review。这不仅提升个人能力，还培养了协作意识。

总结：实习让我从“会写代码”成长为“能解决业务问题”的工程师，技术深度与工程思维并重。'),
