我选择这个项目主要基于**业务痛点驱动**和**技术深度挑战**两方面考虑。

**第一，解决线上推理性能瓶颈（Why）。**
在之前的业务中，我们使用 Python 部署深度学习模型，虽然开发快，但在高并发场景下，GIL 锁和解释器开销导致 P99 延迟超过 200ms，无法满足实时交互需求。
*   **怎么做**：我决定用 C++ 重构推理引擎。通过**模型量化**（FP32 转 INT8）减少内存占用，并利用**算子融合**技术减少内核启动开销。
*   **架构示意**：
    ```text
    Client -> gRPC Gateway -> C++ Inference Service (ThreadPool)
                                        |
                                  [Model Loader] -> [Quantized Model]
                                        |
                                  [Custom Operators] -> [CUDA/OpenCL]
    ```

**第二，探索算法工程化最佳实践（How）。**
算法落地不仅是调参，更是系统工程。我想验证如何在保证精度的前提下，最大化吞吐。
*   **怎么做**：我设计了**异步批处理（Batching）**机制，动态聚合请求以减少 GPU 空闲。同时，针对内存管理，我实现了**对象池（Object Pool）**复用 Tensor 内存，避免频繁 malloc/free。
*   **核心代码逻辑**：
    ```cpp
    // 伪代码：动态批处理
    if (batch_queue.size() >= max_batch || wait_time > timeout) {
        run_inference(batch_queue); 
        batch_queue.clear();
    }
    ```

**第三，业务价值与个人成长（Value）。**
项目上线后，QPS 提升了 5 倍，服务器成本降低 40%。
