### 实习业务模块架构设计（参考答案）

**整体架构采用分层解耦设计**，分为数据接入层、实时处理层、服务层和存储层，核心目标是**高吞吐、低延迟、可扩展**。以下分模块说明：

---

#### 1. **数据接入层**  
- **为什么**：需统一处理多源异构数据（如用户行为日志、车辆传感器数据），避免下游模块直接耦合数据源。  
- **怎么做**：  
  - 使用 **Kafka** 作为消息队列，按业务主题分区（如 `user_clicks`、`vehicle_telemetry`），实现数据缓冲与削峰。  
  - 示例：  
    ```python
    # 生产者示例（用户点击事件上报）
    producer.send(''user_clicks'', value=json.dumps({''user_id'': 123, ''car_id'': 456}))
    ```

---

#### 2. **实时处理层**  
- **为什么**：需对实时数据流进行清洗、特征工程，并触发模型推理（如推荐系统）。  
- **怎么做**：  
  - 基于 **Flink** 构建流处理管道，通过 CEP 规则引擎识别用户行为模式（如连续点击3辆同品牌车）。  
  - 模型服务通过 **gRPC** 调用预训练模型（如 TensorFlow Serving），返回推荐结果。  
  - 示例：  
    ```java
    // Flink CEP 规则（检测用户兴趣转移）
    Pattern<Event, ?> pattern = Pattern.<Event>begin("start")
        .where(event -> event.getBrand() == "Tesla")
        .times(3);
    ```

---

#### 3. **服务层与存储层**  
- **为什么**：需平衡读写性能与数据一致性，支持高并发查询（如车辆详情页）。  
- **怎么做**：  
  - **Redis** 缓存热点数据（如车辆配置信息），**MySQL** 存储核心交易数据。  
  - 通过 **分库分表** 解决单表瓶颈（如按 `car_id` 哈希分片）。  
  - 架构图：  
    ```
    Client -> API Gateway -> [Auth Service] -> [Recommend Service] -> Redis/MySQL
                                  |-> [Real-time Feature Store] -> Flink
    ```

---

#### 4. **扩展性设计**  
- **为什么**：业务增长需动态扩容（如双11期间流量激增）。  
- **怎么做**：  
  - 服务层通过 **Kubernetes** 实现弹性伸缩，结合 Prometheus 监控 QPS 自动调整 Pod 数量。  
  - 存储层通过 **TiDB** 分布式数据库替代 MySQL，支持水平扩展。

---

**总结**：该架构通过**流批一体**处理（Flink + Kafka）、**缓存分层**（Redis + MySQL）和**服务网格化**（K8s），在保障实时性的同时兼顾成本，已支撑日均亿级事件处理。'),
