### 参考答案：

在项目中我主要使用了**策略模式**，尤其在支付模块的设计中。以下是具体说明：

---

#### **1. 为什么选择策略模式？**
- **问题背景**：支付系统需要支持多种支付方式（如支付宝、微信、银行卡），若用大量 `if-else` 或 `switch` 判断，会导致代码臃肿且难以扩展。
- **核心优势**：
  - **开闭原则**：新增支付方式时无需修改现有代码，只需添加新策略类。
  - **单一职责**：每个支付逻辑独立封装，降低耦合度。
  - **动态切换**：通过上下文动态选择策略，提升灵活性。

---

#### **2. 如何应用策略模式？**
- **核心结构**：
  ```java
  // 策略接口
  public interface PaymentStrategy {
      void pay(double amount);
  }

  // 具体策略实现
  public class AlipayStrategy implements PaymentStrategy {
      @Override
      public void pay(double amount) {
          // 支付宝支付逻辑
      }
  }

  public class WechatStrategy implements PaymentStrategy {
      @Override
      public void pay(double amount) {
          // 微信支付逻辑
      }
  }

  // 上下文
  public class PaymentContext {
      private PaymentStrategy strategy;
      public void setStrategy(PaymentStrategy strategy) { this.strategy = strategy; }
      public void executePay(double amount) { strategy.pay(amount); }
  }
  ```
- **调用流程**：
  ```java
  PaymentContext context = new PaymentContext();
  context.setStrategy(new AlipayStrategy()); // 动态选择策略
  context.executePay(100.0);
  ```

- **架构图**：
  ```
  PaymentContext |-> PaymentStrategy
                 |-> AlipayStrategy
                 |-> WechatStrategy
  ```

---

#### **3. 实际场景与效果**
- **场景**：在订单支付环节，用户选择支付方式后，系统通过策略模式动态调用对应支付逻辑。
- **效果**：
  - 新增支付方式（如数字人民币）时，仅需新增 `DigitalRMBStrategy` 类，无需改动核心代码。
  - 测试时可通过注入不同策略快速验证支付流程。

---

#### **4. 与其他模式的结合**
- **工厂模式**：通过工厂类根据配置动态创建策略实例，避免硬编码。
  ```java
  public class PaymentFactory {
      public static PaymentStrategy create(String type) {
          return switch (type) {
              case "alipay" -> new AlipayStrategy();
              case "wechat" -> new WechatStrategy();
              default -> throw new IllegalArgumentException();
          };
      }
  }
  ```

---

### **总结**
策略模式通过**抽象支付行为**和**动态策略切换**，解决了多条件分支的痛点，同时提升了代码的可维护性和扩展性。这种设计在支付、路由分发等场景中具有普适性，是平衡灵活性与性能的经典方案。'),
