### 参考答案：

**1. 高并发秒杀场景下的库存超卖问题**  
**为什么**：传统数据库操作在高并发下容易出现库存超卖，例如多个请求同时读取同一库存值并执行扣减。  
**怎么做**：  
- 引入Redis预减库存，通过Lua脚本保证原子性操作。例如：  
  ```lua
  -- Lua脚本示例
  if redis.call(''get'', KEYS[1]) >= tonumber(ARGV[1]) then
      return redis.call(''decrby'', KEYS[1], ARGV[1])
  else
      return -1
  end
  ```  
- 异步落库：通过消息队列（如Kafka）削峰，将订单写入数据库，避免瞬时压力。  

**2. 数据库性能瓶颈**  
**为什么**：大量请求直接访问MySQL，导致连接池耗尽和慢查询。  
**怎么做**：  
- 分库分表：按用户ID哈希拆分订单表，结合ShardingSphere实现路由。  
- 读写分离：主库写、从库读，通过MyCat配置动态数据源。  
- 架构示例：  
  ```
  Client -> API Gateway -> Order Service -> Redis (库存)  
  |-> Kafka (异步订单) -> Order Service -> MySQL (分片)
  ```  

**3. 缓存一致性保障**  
**为什么**：缓存与数据库数据不一致会导致业务异常。  
**怎么做**：  
- 采用“延迟双删”策略：更新数据库后，先删缓存，再异步重试删除。  
- 使用Canal监听MySQL binlog，实时同步缓存变更。  

**总结**：通过分层解耦（缓存+队列+分库）和原子操作，将QPS从500提升至5000+，错误率降至0.1%以下。'),
