### 参考答案（Java后端面试）

#### 1. **架构设计差异：高并发 vs 数据一致性**
**为什么**：  
电商系统需应对瞬时流量峰值（如秒杀），而数据平台更关注复杂事务的ACID特性。  
**怎么做**：  
- **电商项目**：采用微服务+异步解耦架构  
  ```mermaid
  Client -> API Gateway -> Auth Service -> Order Service -> MySQL  
  |-> RabbitMQ -> Inventory Service (库存扣减)  
  ```  
  通过Redis分布式锁+消息队列削峰，订单服务与库存服务异步交互。  
- **数据平台**：使用单体架构+强一致性事务  
  核心模块通过`@Transactional`保证跨表操作原子性，例如：  
  ```java
  @Transactional  
  public void processReport() {  
      updateMetrics(); // 更新指标表  
      generateReport(); // 生成报表  
  }  
  ```

#### 2. **性能优化方向：缓存策略 vs 计算优化**
**为什么**：  
电商系统读多写少，需降低数据库压力；数据平台需高效处理海量数据计算。  
**怎么做**：  
- **电商项目**：多级缓存架构  
  ```java
  // Redis缓存商品详情  
  @Cacheable(value="product", key="#id")  
  public Product getProduct(Long id) { ... }  
  ```  
  结合本地缓存（Caffeine）减少网络开销。  
- **数据平台**：SQL执行计划优化  
  对千万级订单表建立复合索引`(status, create_time)`，并通过分区表按月份拆分历史数据。

#### 3. **技术栈选择：实时性 vs 批处理能力**
**为什么**：  
电商需实时库存同步，数据平台侧重离线ETL任务。  
**怎么做**：  
- **电商项目**：Flink实时计算库存  
  ```java
  // 消费Kafka订单消息更新库存  
  stream.map(new OrderMapper()).keyBy(Order::getProductId)  
        .window(TumblingEventTimeWindows.of(Time.minutes(1)))  
        .process(new StockUpdateFunction());  
  ```  
- **数据平台**：Spark批处理报表生成  
  使用DataFrame API聚合订单数据：  
  ```scala
  val report = ordersDF.groupBy("date").agg(sum("amount"))  
  ```

#### 4. **团队协作模式：敏捷迭代 vs 工程规范**
**为什么**：  
电商需求变化快需快速响应，数据平台需严格遵循数据治理规范。  
**怎么做**：  
- **电商项目**：采用DevOps流水线  
  Jenkins自动触发SonarQube代码扫描+K8s滚动发布。  
- **数据平台**：制定数据血缘文档规范  
  使用DataX配置元数据同步任务，确保上下游字段映射可追溯。

